import { createFileRoute } from "@tanstack/react-router";
import { t } from "@/game/i18n";
import { LegalPage, usePageLang } from "@/components/legal/LegalPage";
// Generated by `npm run licenses` (scripts/gen-licenses.mjs); do not edit by hand.
import notices from "@/game/licenses.generated.json";

export const Route = createFileRoute("/licenses")({
  head: () => ({ meta: [{ title: "Licenses · STAR" }] }),
  component: LicensesPage,
});

function LicensesPage() {
  const lang = usePageLang();
  const tr = (key: string) => t(key, undefined, lang);
  return (
    <LegalPage title={tr("legal.licenses")} lang={lang}>
      <p>{tr("lic.lead")}</p>

      <h2 className="mt-2 text-base font-semibold text-fg">{tr("lic.fonts")}</h2>
      <ul className="grid gap-2" dir="ltr">
        {notices.fonts.map((font) => (
          <li key={font.name} className="card px-4 py-3">
            <a href={font.notice} className="font-semibold text-fg">
              {font.name}
            </a>
            <span className="text-xs"> · SIL OFL 1.1</span>
            {font.copyright.map((line) => (
              <p key={line} className="text-xs">
                {line}
              </p>
            ))}
          </li>
        ))}
      </ul>

      <h2 className="mt-2 text-base font-semibold text-fg">
        {tr("lic.packages")} <span className="num text-muted">{notices.packages.length}</span>
      </h2>
      <ul className="grid gap-2" dir="ltr">
        {notices.packages.map((p) => (
          <li key={`${p.name}@${p.version}`} className="border-b border-line pb-2">
            <span className="font-semibold text-fg">{p.url ? <a href={p.url}>{p.name}</a> : p.name}</span>
            <span className="text-xs">
              {" "}
              {p.version} · {p.license}
            </span>
            {p.copyright.map((line) => (
              <p key={line} className="text-xs">
                {line}
              </p>
            ))}
          </li>
        ))}
      </ul>

      <h2 className="mt-2 text-base font-semibold text-fg">{tr("lic.texts")}</h2>
      <div className="grid gap-2" dir="ltr">
        {Object.entries(notices.texts as Record<string, string>).map(([id, text]) => (
          <details key={id} className="card px-4 py-3">
            <summary className="min-h-8 cursor-pointer font-semibold text-fg">{id}</summary>
            <pre className="mt-2 whitespace-pre-wrap break-words font-sans text-xs leading-5">{text}</pre>
          </details>
        ))}
      </div>
    </LegalPage>
  );
}
